type BinaryTree<T> =
  | { kind: 'leaf' }
  | { kind: 'node'; value: T; left: BinaryTree<T>; right: BinaryTree<T> }

// Función que explota el tipo recursivo
function depth<T>(t: BinaryTree<T>): number {
  if (t.kind === 'leaf') return 0
  return 1 + Math.max(depth(t.left), depth(t.right))
}

